INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cfe4', 6, 'Once everything is done, add the rice, raisins & spices to the veggies and add 2 and a half cups of water for the rice to cook.');
